code='''from collections import deque

def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    colors={v for row in g for v in row if v not in (0,)}
    # The nonzero accent object is the shape to stamp into matching zero cells.
    counts={c:sum(v==c for row in g for v in row) for c in colors}
    color=min(colors,key=lambda c: counts[c])
    cells={(r,c) for r in range(h) for c in range(w) if g[r][c]==color}
    # keep the connected accent object (4-connectivity)
    seed={next(iter(cells))}; q=list(seed)
    for r,c in q:
        for x,y in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if (x,y) in cells and (x,y) not in seed:
                seed.add((x,y)); q.append((x,y))
    r0=min(r for r,c in seed); c0=min(c for r,c in seed)
    shape={(r-r0,c-c0) for r,c in seed}
    sh=max(r for r,c in shape)+1; sw=max(c for r,c in shape)+1
    for i in range(h-sh+1):
        for j in range(w-sw+1):
            points={(i+r,j+c) for r,c in shape}
            if all(g[r][c]==0 for r,c in points):
                for r,c in points: g[r][c]=color
    return g
'''
